// Tournament series and their broadcast links come from the same Spectate record.
function esportsDotaSeries(data,now=Date.now()){
 const fetched=Date.parse(data?.fetchedAt);if(!Number.isFinite(fetched)||fetched>now+60000||now-fetched>5*60000||!Array.isArray(data?.matches))return [];
 const out=[];for(const m of data.matches.slice(0,40)){const home=String(m?.teamA||'').trim().slice(0,100),away=String(m?.teamB||'').trim().slice(0,100),game=(Array.isArray(m.games)?m.games:[]).find(g=>g.status==='running'),started=Date.parse(game?.beginAt);if(!/^\d{1,20}$/.test(String(m?.id||''))||!home||!away||!game||!Number.isFinite(started)||started>now+60000||now-started>12*3600000)continue;
  const scores=String(m.seriesScore||'').match(/^(\d{1,2})\s*[-:]\s*(\d{1,2})$/),broadcasts=[],seen=new Set();for(const st of Array.isArray(m.allStreams)?m.allStreams:[]){let u;try{u=new URL(st.raw_url);}catch{continue;}if(u.protocol!=='https:'||u.username||u.password)continue;let provider='',id='';if(['twitch.tv','www.twitch.tv'].includes(u.hostname)){provider='twitch';id=u.pathname.slice(1);}else if(['youtube.com','www.youtube.com','m.youtube.com'].includes(u.hostname)&&u.pathname==='/watch'){provider='youtube';id=u.searchParams.get('v')||'';}else if(u.hostname==='youtu.be'){provider='youtube';id=u.pathname.slice(1);}if(provider==='twitch'&&!/^[a-z0-9_]{3,25}$/i.test(id)||provider==='youtube'&&!/^[\w-]{11}$/.test(id)||!provider)continue;const key=provider+':'+(provider==='twitch'?id.toLowerCase():id);if(seen.has(key))continue;seen.add(key);broadcasts.push({provider,id,confirmed:true,name:provider==='youtube'?'YouTube':id,title:'Трансляция матча · Spectate Esports'+(st.language?' · '+String(st.language).slice(0,12):'')});}
  out.push({id:'spectate:'+m.id,home,away,homeScore:scores?.[1]||'',awayScore:scores?.[2]||'',league:String(m.tournament||'Dota 2').slice(0,100),broadcasts,live:true});
 }return out;
}
function esportsDotaSeriesRows(items,tv=false){if(!items.length)return '';return '<section class="'+(tv?'sec':'section sport-section')+' sport-esports"><div class="sec-head"><h2>Dota 2 · турнирные матчи</h2></div><p class="'+(tv?'sub':'hint')+'">Spectate Esports · счёт серии и доступные трансляции</p><div class="'+(tv?'track':'sport-rail')+'">'+items.map((x,i)=>`<button class="match-card esports-card ${tv?'f':''}" ${tv?'tabindex="-1" data-k="dota-series:'+i+'"':''} data-dota-series="${i}"><div class="match-top"><span>${esc(x.league)}</span><span>● ИДЁТ ИГРА</span></div><div class="match-team"><b>${esc(x.home)}</b><strong>${esc(x.homeScore)}</strong></div><div class="match-team"><b>${esc(x.away)}</b><strong>${esc(x.awayScore)}</strong></div></button>`).join('')+'</div></section>';}

// Cito publishes match-specific broadcasts in its public dashboard data.
// Decode Next.js data as JSON only; never execute scripts from the remote page.
function esportsCitoStreams(html, match, now=Date.now()) {
  const id=String(match?.id||'').match(/^csgo_mc_(\d{1,16})$/);
  if(!id||!match.live||typeof html!=='string'||html.length>1500000)return [];
  const norm=s=>String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
  const eq=(a,b)=>{a=norm(a);b=norm(b);if(!a||!b)return false;if(a===b)return true;return (a==='vp'&&b==='virtus pro')||(b==='vp'&&a==='virtus pro');};
  const scripts=html.matchAll(/<script>self\.__next_f\.push\((\[[\s\S]*?\])\)<\/script>/g);
  for(const script of scripts){let chunk;try{chunk=JSON.parse(script[1])[1];}catch{continue;}if(typeof chunk!=='string'||!chunk.includes('cs2-match-'+id[1]))continue;
    for(const marker of chunk.matchAll(/"matches":\s*\[/g)){const start=marker.index+marker[0].lastIndexOf('[');let depth=0,quoted=false,escaped=false,end=-1;
      for(let i=start;i<chunk.length;i++){const c=chunk[i];if(quoted){if(escaped)escaped=false;else if(c==='\\')escaped=true;else if(c==='"')quoted=false;}else if(c==='"')quoted=true;else if(c==='[')depth++;else if(c===']'&&!--depth){end=i+1;break;}}
      if(end<0)continue;let rows;try{rows=JSON.parse(chunk.slice(start,end));}catch{continue;}if(!Array.isArray(rows))continue;
      const row=rows.find(x=>x?.id==='cs2-match-'+id[1]&&x.status==='live');if(!row)continue;
      const starts=Date.parse(row.startsAt),verified=Date.parse(row.last_verified||row.lastVerified);if(!Number.isFinite(starts)||Math.abs(starts-Number(match.date))>3*3600000||!Number.isFinite(verified)||verified>now+60000||now-verified>20*60000)return [];
      if(!((eq(row.team1Name,match.home)&&eq(row.team2Name,match.away))||(eq(row.team1Name,match.away)&&eq(row.team2Name,match.home))))return [];
      const out=[],seen=new Set();for(const stream of Array.isArray(row.streamLinks)?row.streamLinks:[]){let u;try{u=new URL(stream.url);}catch{continue;}if(u.protocol!=='https:'||u.username||u.password)continue;let provider='',key='';
        if(['www.youtube.com','youtube.com','m.youtube.com'].includes(u.hostname)&&u.pathname==='/watch'){provider='youtube';key=u.searchParams.get('v')||'';}else if(u.hostname==='youtu.be'){provider='youtube';key=u.pathname.slice(1);}else if(['www.twitch.tv','twitch.tv'].includes(u.hostname)){provider='twitch';key=u.pathname.slice(1);}
        if(provider==='youtube'&&!/^[\w-]{11}$/.test(key)||provider==='twitch'&&!/^[a-z0-9_]{3,25}$/i.test(key)||!provider)continue;const unique=provider+':'+(provider==='twitch'?key.toLowerCase():key);if(seen.has(unique))continue;seen.add(unique);out.push({provider,id:key,confirmed:true,name:String(stream.label||(provider==='youtube'?'YouTube':key)).slice(0,100),title:'Трансляция матча · Cito'+(stream.language?' · '+String(stream.language).slice(0,12):'')});
      }return out.slice(0,20);
    }
  }return [];
}


// YouTube search results are suggestions only; accept only explicitly live videos.
function esportsYoutubeLiveResults(html) {
  const marker = /(?:var\s+ytInitialData\s*=|ytInitialData\s*=)\s*/.exec(String(html || ''));
  if (!marker) return [];
  const start = marker.index + marker[0].length;
  let depth=0, quoted=false, escaped=false, end=-1;
  for (let i=start;i<html.length;i++) { const c=html[i]; if(quoted){if(escaped)escaped=false;else if(c==='\\')escaped=true;else if(c==='"')quoted=false;}else if(c==='"')quoted=true;else if(c==='{')depth++;else if(c==='}'&&!--depth){end=i+1;break;} }
  if(end<0)return [];
  let data;try{data=JSON.parse(html.slice(start,end));}catch{return [];}
  const out=[], seen=new Set(), stack=[data];let visited=0;
  const text=x=>x?.simpleText||(x?.runs||[]).map(r=>r.text||'').join('');
  while(stack.length && visited++<50000 && out.length<40){const node=stack.pop();if(!node||typeof node!=='object')continue;
    const v=node.videoRenderer;if(v&&/^[\w-]{11}$/.test(v.videoId||'')){
      const flags=JSON.stringify([v.badges||[],v.thumbnailOverlays||[]]);
      if(/"(?:LIVE|BADGE_STYLE_TYPE_LIVE_NOW)"/.test(flags)&&!v.upcomingEventData&&!seen.has(v.videoId)){
        seen.add(v.videoId);out.push({provider:'youtube',id:v.videoId,title:text(v.title).slice(0,240),name:text(v.ownerText||v.shortBylineText).slice(0,100)||'YouTube'});
      }
    }
    for(const value of Object.values(node).reverse())if(value&&typeof value==='object')stack.push(value);
  }
  return out;
}

'use strict';
function esportsMatchLabel(title){const text=String(title||'').replace(/\s+/g,' ').trim();const part=text.split(/\s*[|｜•·]|\s+-\s+|\p{So}+/u).find(x=>/(?:\bvs?\.?\b|\bversus\b|против)/i.test(x))||text;return part.replace(/\s+(?:w\/|with\s+@|!|@).*/i,'').replace(/^\s*\[[^\]]+\]\s*/, '').trim()||text;}
function sportEta(value){const text=String(value||'').trim();if(!/^upcoming/i.test(text))return text||'СКОРО';const rest=text.replace(/^upcoming\s*/i,'').trim();if(!rest||/^0(?:h|m|s)(?:\s+0(?:h|m|s))*$/i.test(rest))return 'СКОРО';return 'Через '+rest.replace(/(\d+)h\b/gi,'$1 ч').replace(/(\d+)m\b/gi,'$1 мин').replace(/(\d+)s\b/gi,'$1 с');}
function esportsOffTopic(title){return /minecraft|майнкрафт|league of legends|\bvalorant\b|\bdota\s*2\b|grand theft auto|\bgta\s*(?:v|vi|5|6)\b|world of warcraft|\bwow\b/i.test(String(title||''));}
function esportsLooksLikeMatch(title){return /\bvs?\.?\b|\bversus\b|(?:^|\s)против(?:\s|$)/i.test(String(title||''));}
function esportsMatchHeader(card){if(!card)return '';const teams=[...card.querySelectorAll('.match-team')].slice(0,2).map(x=>({name:x.querySelector('b')?.textContent?.trim()||'',score:x.querySelector('strong')?.textContent?.trim()||''}));if(teams.length!==2||teams.some(x=>!x.name))return '';const scores=teams.every(x=>x.score)?'<strong>'+esc(teams[0].score)+'</strong><i>:</i><strong>'+esc(teams[1].score)+'</strong>':'<span>VS</span>';return '<div class="sport-event-scoreboard esports-event-scoreboard">'+teams.map((x,i)=>'<div class="sport-event-team '+(i?'away':'')+'"><span class="sport-event-logo esports-initial">'+esc(x.name[0])+'</span><b>'+esc(x.name)+'</b></div>'+(i===0?'<div class="sport-event-score">'+scores+'</div>':'')).join('')+'</div>';}
function sportTransliterate(value){const map={а:'a',б:'b',в:'v',г:'g',д:'d',е:'e',ё:'e',ж:'zh',з:'z',и:'i',й:'y',к:'k',л:'l',м:'m',н:'n',о:'o',п:'p',р:'r',с:'s',т:'t',у:'u',ф:'f',х:'kh',ц:'ts',ч:'ch',ш:'sh',щ:'shch',ъ:'',ы:'y',ь:'',э:'e',ю:'yu',я:'ya'};return String(value||'').replace(/[а-яё]/g,c=>map[c]??c);}
function esportsTeamKeys(name){const norm=s=>String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();const full=norm(name),words=full.split(' ').filter(w=>w&&!['team','gaming','esports','esport','club','dota'].includes(w));const core=words.join(' ');return [...new Set([full,core,sportTransliterate(full),sportTransliterate(core)])].filter(x=>x.replace(/ /g,'').length>=3);}
function esportsTeamsInMatchTitle(title,home,away){
  const keys=name=>{const full=String(name||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();const compact=full.split(' ').filter(w=>w&&!['team','gaming','esports','esport','club','dota'].includes(w)).join(' ');return [...new Set([...esportsTeamKeys(name),full,compact].filter(x=>x.replace(/ /g,'').length>=2))];};
  const a=keys(home),b=keys(away);if(!a.length||!b.length||a.some(x=>b.includes(x)))return false;
  return String(title||'').split(/[|｜•·]/u).some(part=>{const sides=part.split(/\s+(?:vs?\.?|versus|против|x|—|–|-)\s+/i);if(sides.length!==2)return false;const has=(side,aliases)=>{const text=' '+side.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim()+' ';return aliases.some(key=>text.includes(' '+key+' ')||sportTransliterate(text).includes(' '+sportTransliterate(key)+' '));};return has(sides[0],a)&&has(sides[1],b)||has(sides[0],b)&&has(sides[1],a);});
}
function esportsTeamsInTitle(title,home,away){const text=' '+String(title||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim()+' ',texts=[text,sportTransliterate(text)],a=esportsTeamKeys(home),b=esportsTeamKeys(away);return !!(a.length&&b.length&&!a.some(x=>b.includes(x))&&a.some(x=>texts.some(t=>t.includes(' '+x+' ')))&&b.some(x=>texts.some(t=>t.includes(' '+x+' '))));}
function sportFollowStore(){return state.sportFollows||(state.sportFollows={});}
function sportFollowSave(){persist('sportFollows');}
const SPORT_PANEL_LEAGUES=[['РПЛ','soccer/rus.1'],['АПЛ','soccer/eng.1'],['Лига чемпионов','soccer/uefa.champions'],['Ла Лига','soccer/esp.1'],['НБА','basketball/nba'],['НХЛ','hockey/nhl'],['НФЛ','football/nfl'],['МЛБ','baseball/mlb']];
function sportDateKey(d){return String(d.getFullYear())+String(d.getMonth()+1).padStart(2,'0')+String(d.getDate()).padStart(2,'0');}
function sportPanelDate(value){const s=String(value||'');if(!/^\d{8}$/.test(s))return new Date();const d=new Date(Number(s.slice(0,4)),Number(s.slice(4,6))-1,Number(s.slice(6,8)),12);return sportDateKey(d)===s?d:new Date();}
function sportPanelEvents(data,league){return (Array.isArray(data?.events)?data.events:[]).map(e=>{const c=e.competitions?.[0],h=c?.competitors?.find(x=>x.homeAway==='home'),a=c?.competitors?.find(x=>x.homeAway==='away');if(!h||!a||!Number.isFinite(Date.parse(e.date)))return null;const team=x=>({id:String(x.team?.id||''),name:String(x.team?.shortDisplayName||x.team?.displayName||''),logo:String(x.team?.logo||''),score:String(x.score||'')});return {id:String(e.id||''),league,date:String(e.date),state:String(e.status?.type?.state||'pre'),home:team(h),away:team(a)};}).filter(Boolean).sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));}
function sportPanelStandings(data){const groups=[];const walk=(node)=>{if(!node||typeof node!=='object')return;const entries=node.standings?.entries;if(Array.isArray(entries)&&entries.length){const rows=entries.map((e,i)=>{const stats=Object.fromEntries((e.stats||[]).map(x=>[x.name,x]));const val=k=>String(stats[k]?.displayValue??'');const wins=Number(stats.wins?.value),losses=Number(stats.losses?.value),ties=Number(stats.ties?.value);const played=val('gamesPlayed')||([wins,losses,ties].some(Number.isFinite)?String((wins||0)+(losses||0)+(ties||0)):'');const rank=Number(stats.rank?.value||stats.playoffSeed?.value)||i+1;return {rank,name:String(e.team?.displayName||e.team?.shortDisplayName||''),logo:String(e.team?.logos?.[0]?.href||e.team?.logo||''),played,wins:val('wins'),losses:val('losses'),ties:val('ties'),points:val('points'),pct:Number.isFinite(stats.winPercent?.value)?(stats.winPercent.value*100).toFixed(1)+'%':val('winPercent')};}).filter(x=>x.name).sort((a,b)=>a.rank-b.rank);groups.push({name:String(node.name||''),rows});}for(const child of node.children||[])walk(child);};walk(data);return groups;}
function sportStandingsColumns(league){return ['РПЛ','АПЛ','Лига чемпионов','Ла Лига'].includes(league)?['И','В','Н','П','О']:league==='НХЛ'?['И','В','П','О']:['И','В','П','%'];}
function sportStandingsValues(row,league){const dash=x=>x||'—';return ['РПЛ','АПЛ','Лига чемпионов','Ла Лига'].includes(league)?[dash(row.played),dash(row.wins),dash(row.ties),dash(row.losses),dash(row.points)]:league==='НХЛ'?[dash(row.played),dash(row.wins),dash(row.losses),dash(row.points)]:[dash(row.played),dash(row.wins),dash(row.losses),dash(row.pct)];}
const SPORT_PANEL_TV=false;
function sportPanelGo(r){go(r);}
function sportPanelImage(url){return url;}
function sportPanelLoad(panel,league,date){return panel==='calendar'?window.lift.sportCalendar(league,date):window.lift.sportStandings(league);}
function sportPanelBindMatches(target,items){target.querySelectorAll('[data-calendar-match]').forEach(b=>b.onclick=()=>sportMatchDialog(items[Number(b.dataset.calendarMatch)]));}
function sportPanelLeague(r){return SPORT_PANEL_LEAGUES.some(x=>x[0]===r.league)?r.league:(sportActiveFollows().find(x=>SPORT_PANEL_LEAGUES.some(l=>l[0]===x.league))?.league||'РПЛ');}
async function renderSportPanel(view,r,alive){
  const panel=r.panel==='standings'?'standings':'calendar',league=sportPanelLeague(r),date=sportPanelDate(r.date),dateKey=sportDateKey(date),tv=SPORT_PANEL_TV;
  const nav=(patch,focus)=>sportPanelGo({name:'sport',panel,league,date:dateKey,...patch},focus);
  const leagues=SPORT_PANEL_LEAGUES.map(([name],i)=>`<button ${tv?'class="chip f" tabindex="-1" data-k="league:'+i+'"':'class="pill"'} data-panel-league="${i}" aria-pressed="${name===league}">${esc(name)}</button>`).join('');
  view.innerHTML=`<div class="sport-detail-page ${tv?'page':''}"><header class="sport-detail-head"><div><span class="sport-detail-kicker">СПОРТ · ESPN</span><h1>${panel==='calendar'?'Календарь матчей':'Турнирные таблицы'}</h1><p>${panel==='calendar'?'Расписание и результаты выбранной лиги':'Положение команд в текущем сезоне'}</p></div><div class="sport-detail-actions"><button ${tv?'class="chip f" tabindex="-1" data-k="panel:back"':'class="pill"'} data-panel-back>Назад к спорту</button><button ${tv?'class="chip f" tabindex="-1" data-k="panel:switch"':'class="pill"'} data-panel-switch>${panel==='calendar'?'Таблицы':'Календарь'}</button></div></header><div class="sport-league-scroll" aria-label="Лиги">${leagues}</div>${panel==='calendar'?`<div class="sport-date-nav"><button ${tv?'class="chip f" tabindex="-1" data-k="date:prev"':'class="pill"'} data-date-shift="-1" aria-label="Предыдущий день">‹</button><strong>${esc(date.toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long',year:'numeric'}))}</strong><button ${tv?'class="chip f" tabindex="-1" data-k="date:next"':'class="pill"'} data-date-shift="1" aria-label="Следующий день">›</button><button ${tv?'class="chip f" tabindex="-1" data-k="date:today"':'class="pill"'} data-date-today>Сегодня</button></div>`:''}<div class="sport-detail-content" data-panel-content><p class="sport-panel-notice">Загружаем данные…</p></div></div>`;
  view.querySelector('[data-panel-back]').onclick=()=>sportPanelGo({name:'sport'});
  view.querySelector('[data-panel-switch]').onclick=()=>nav({panel:panel==='calendar'?'standings':'calendar'});
  view.querySelectorAll('[data-panel-league]').forEach(b=>b.onclick=()=>nav({league:SPORT_PANEL_LEAGUES[Number(b.dataset.panelLeague)][0]},'league:'+b.dataset.panelLeague));
  view.querySelectorAll('[data-date-shift]').forEach(b=>b.onclick=()=>{const d=new Date(date);d.setDate(d.getDate()+Number(b.dataset.dateShift));nav({date:sportDateKey(d)},Number(b.dataset.dateShift)<0?'date:prev':'date:next');});
  const today=view.querySelector('[data-date-today]');if(today)today.onclick=()=>nav({date:sportDateKey(new Date())},'date:today');
  const target=view.querySelector('[data-panel-content]');let result;try{result=await sportPanelLoad(panel,league,dateKey);}catch{result={error:true};}if(!alive()||!target.isConnected)return;
  if(result.error){target.innerHTML='<div class="sport-panel-notice"><b>Данные временно недоступны</b><p>Попробуйте загрузить ещё раз.</p><button '+(tv?'class="chip f" tabindex="-1" data-k="panel:retry"':'class="pill"')+' data-panel-retry>Повторить</button></div>';target.querySelector('[data-panel-retry]').onclick=async()=>{await renderSportPanel(view,{...r,panel,league,date:dateKey},alive);if(alive())(view.querySelector('[data-panel-retry]')||view.querySelector('[data-panel-league][aria-pressed=true]'))?.focus({preventScroll:true});};return;}
  if(panel==='calendar'){
    const items=sportPanelEvents(result.data,league);if(!items.length){target.innerHTML='<div class="sport-panel-notice"><b>Матчей на этот день нет</b><p>Выберите другую дату или лигу.</p></div>';return;}
    target.innerHTML='<div class="sport-calendar-list">'+items.map((m,i)=>`<button class="sport-calendar-row ${tv?'f':''}" ${tv?'tabindex="-1" data-k="calendar:'+i+'"':''} data-calendar-match="${i}"><span class="sport-calendar-time">${m.state==='in'?'● LIVE':esc(new Date(m.date).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}))}</span><span class="sport-calendar-teams">${[m.home,m.away].map(t=>`<span>${t.logo?`<img src="${esc(sportPanelImage(t.logo))}" alt="">`:''}<b>${esc(t.name)}</b></span>`).join('')}</span><strong class="sport-calendar-score">${m.state==='pre'?'VS':esc((m.home.score||'—')+' : '+(m.away.score||'—'))}</strong><span aria-hidden="true">›</span></button>`).join('')+'</div>';
    sportPanelBindMatches(target,items);return;
  }
  const groups=sportPanelStandings(result.data),columns=sportStandingsColumns(league);if(!groups.length){target.innerHTML='<div class="sport-panel-notice"><b>Таблица пока недоступна</b><p>Источник не вернул положение команд для этой лиги.</p></div>';return;}
  target.innerHTML=groups.map(g=>`<section class="sport-standings-group"><h2>${esc(g.name||league)}</h2><div class="sport-standing-head" style="--sport-cols:${columns.length}"><span>#</span><span>Команда</span>${columns.map(c=>`<span>${c}</span>`).join('')}</div>${g.rows.map((row,i)=>`<${tv?'button':'div'} class="sport-standing-row ${tv?'f':''}" ${tv?'tabindex="-1" data-k="standing:'+esc(g.name)+':'+i+'"':''} style="--sport-cols:${columns.length}"><span>${row.rank}</span><span class="sport-standing-team">${row.logo?`<img src="${esc(sportPanelImage(row.logo))}" alt="">`:''}<b>${esc(row.name)}</b></span>${sportStandingsValues(row,league).map(v=>`<span>${esc(v)}</span>`).join('')}</${tv?'button':'div'}>`).join('')}</section>`).join('');
}
